import{_ as o,o as a,c as r,a2 as i}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"3.5 安全标识与警示标志","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-5-an-quan-biao-shi-yu-jing-shi-biao-zhi.md","filePath":"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-5-an-quan-biao-shi-yu-jing-shi-biao-zhi.md","lastUpdated":1793095197000}'),l={name:"electrician/low-voltage-electrician/03-chapter-3-dian-qi-an-quan-ji-chu-zhi-shi/3-5-an-quan-biao-shi-yu-jing-shi-biao-zhi.md"};function n(e,t,s,d,u,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_3-5-安全标识与警示标志" tabindex="-1">3.5 安全标识与警示标志 <a class="header-anchor" href="#_3-5-安全标识与警示标志" aria-label="Permalink to &quot;3.5 安全标识与警示标志&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>工地上、配电房里满墙的红黄蓝绿标志,不是装饰——它们用颜色和图形&quot;说话&quot;,提醒你该做什么、不该做什么。这一节把<strong>安全色的含义</strong>和<strong>四类安全标志</strong>讲清楚,考试里&quot;这个标志表示什么&quot;是送分题。</p><h2 id="一、安全色-必背" tabindex="-1">一、安全色(必背) <a class="header-anchor" href="#一、安全色-必背" aria-label="Permalink to &quot;一、安全色(必背)&quot;">​</a></h2><p>安全色是表示安全信息含义的颜色,共四种:</p><table tabindex="0"><thead><tr><th>安全色</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>红色</strong></td><td><strong>禁止、停止、危险</strong></td><td>&quot;禁止合闸&quot;&quot;禁止烟火&quot;</td></tr><tr><td><strong>黄色</strong></td><td><strong>警告、注意</strong></td><td>&quot;当心触电&quot;&quot;注意安全&quot;</td></tr><tr><td><strong>蓝色</strong></td><td><strong>指令、必须遵守</strong></td><td>&quot;必须戴绝缘手套&quot;&quot;必须穿绝缘鞋&quot;</td></tr><tr><td><strong>绿色</strong></td><td><strong>安全、提示、通行</strong></td><td>&quot;安全出口&quot;&quot;急救点&quot;</td></tr></tbody></table><blockquote><p>💡 记忆口诀:<strong>&quot;红禁、黄警、蓝令、绿通&quot;</strong>。</p></blockquote><p><strong>对比色</strong>:标志色与对比色配合使用更醒目——红配白、黄配黑、蓝配白、绿配白。</p><h2 id="二、四类安全标志" tabindex="-1">二、四类安全标志 <a class="header-anchor" href="#二、四类安全标志" aria-label="Permalink to &quot;二、四类安全标志&quot;">​</a></h2><h3 id="_1-禁止标志" tabindex="-1">1. 禁止标志 <a class="header-anchor" href="#_1-禁止标志" aria-label="Permalink to &quot;1. 禁止标志&quot;">​</a></h3><ul><li><strong>形状</strong>:红色圆形 + 红色斜杠;</li><li><strong>含义</strong>:禁止某种危险行为;</li><li><strong>例子</strong>:禁止合闸、禁止烟火、禁止触摸。</li></ul><h3 id="_2-警告标志" tabindex="-1">2. 警告标志 <a class="header-anchor" href="#_2-警告标志" aria-label="Permalink to &quot;2. 警告标志&quot;">​</a></h3><ul><li><strong>形状</strong>:黄色三角形、黑色边框、黑色图形;</li><li><strong>含义</strong>:提醒注意危险;</li><li><strong>例子</strong>:当心触电、注意安全、当心机械伤人。</li></ul><h3 id="_3-指令标志" tabindex="-1">3. 指令标志 <a class="header-anchor" href="#_3-指令标志" aria-label="Permalink to &quot;3. 指令标志&quot;">​</a></h3><ul><li><strong>形状</strong>:蓝色圆形;</li><li><strong>含义</strong>:必须执行的规定动作;</li><li><strong>例子</strong>:必须戴安全帽、必须戴绝缘手套、必须穿绝缘鞋。</li></ul><h3 id="_4-提示标志" tabindex="-1">4. 提示标志 <a class="header-anchor" href="#_4-提示标志" aria-label="Permalink to &quot;4. 提示标志&quot;">​</a></h3><ul><li><strong>形状</strong>:绿色正方形;</li><li><strong>含义</strong>:提供安全信息、指示安全地点;</li><li><strong>例子</strong>:安全出口、太平门、急救点、应急电话。</li></ul><h2 id="三、电工专用标示牌-重点" tabindex="-1">三、电工专用标示牌(重点) <a class="header-anchor" href="#三、电工专用标示牌-重点" aria-label="Permalink to &quot;三、电工专用标示牌(重点)&quot;">​</a></h2><p>电气作业现场的标示牌,是<strong>安全技术措施</strong>的一部分(配合停电、验电、挂地线使用),常见的有:</p><table tabindex="0"><thead><tr><th>标示牌</th><th>颜色</th><th>使用场合</th></tr></thead><tbody><tr><td><strong>&quot;禁止合闸,有人工作!&quot;</strong></td><td>白底红字</td><td>设备检修时挂在该设备的操作开关上</td></tr><tr><td><strong>&quot;禁止合闸,线路有人工作!&quot;</strong></td><td>白底红字</td><td>线路检修时挂在相关线路开关上</td></tr><tr><td><strong>&quot;止步,高压危险!&quot;</strong></td><td>白底黑字红边</td><td>高压设备、遮栏入口</td></tr><tr><td><strong>&quot;在此工作!&quot;</strong></td><td>绿底白字</td><td>指定工作地点</td></tr><tr><td><strong>&quot;从此上下!&quot;</strong></td><td>绿底白字</td><td>允许攀登的构架</td></tr></tbody></table><blockquote><p>⚠️ 考点:检修时在开关上挂&quot;<strong>禁止合闸,有人工作!</strong>&quot;标示牌,是为了防止他人误送电——这是保命的牌子。</p></blockquote><h2 id="四、安全标志的补充要求" tabindex="-1">四、安全标志的补充要求 <a class="header-anchor" href="#四、安全标志的补充要求" aria-label="Permalink to &quot;四、安全标志的补充要求&quot;">​</a></h2><ul><li>标志应设置在醒目的位置,与安全有关;</li><li>标志牌要经常检查、保持清洁完好,损坏、褪色的要及时更换;</li><li>安全标志的颜色和图形有国家标准,不能随意更改。</li></ul><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 安全色:红=禁止、黄=警告、蓝=指令、绿=提示(通行/安全)。</li><li>✅ 四类标志形状:禁止(红圆斜杠)、警告(黄三角)、指令(蓝圆)、提示(绿方)。</li><li>✅ 检修挂&quot;禁止合闸,有人工作!&quot;标示牌。</li><li>⚠️ 易混点:黄三角(警告)和蓝圆(指令)别混——一个&quot;提醒你危险&quot;,一个&quot;要求你去做&quot;。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>安全色:红禁、黄警、蓝令、绿通。</li><li>四类标志:禁止、警告、指令、提示。</li><li>电工现场标示牌是防误送电、防误入的关键安全措施。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)表示&quot;禁止、停止&quot;的安全色是()。 A. 红色　B. 黄色　C. 蓝色　D. 绿色</li><li>(单选)三角形黄底黑边的标志属于()标志。 A. 禁止　B. 警告　C. 指令　D. 提示</li><li>(判断)设备检修时,应在操作开关上悬挂&quot;禁止合闸,有人工作!&quot;标示牌。( )</li><li>(单选)绿色方形标志表示()。 A. 禁止　B. 警告　C. 指令　D. 安全提示</li><li>(判断)安全标志损坏或褪色后,应及时更换。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>A</strong>。红色表示禁止、停止、危险。</li><li><strong>B</strong>。黄底黑边三角形是警告标志。</li><li><strong>√</strong>。防止他人误送电,是安全技术措施之一。</li><li><strong>D</strong>。绿色方形是提示(安全、通行)标志。</li><li><strong>√</strong>。标志要完好醒目,损坏褪色应及时更换。</li></ol></details>',30)])])}const c=o(l,[["render",n]]);export{g as __pageData,c as default};
